import{H as e,V as t,et as n,j as r}from"./chunks/framework.Dj60FFN6.js";var i=JSON.parse(`{"title":"Doppia deduzione logica","description":"","frontmatter":{},"headers":[],"relativePath":"lezioni/k_logica/kb/kbi.md","filePath":"lezioni/k_logica/kb/kbi.md"}`),a={name:`lezioni/k_logica/kb/kbi.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="doppia-deduzione-logica" tabindex="-1">Doppia deduzione logica <a class="header-anchor" href="#doppia-deduzione-logica" aria-label="Permalink to “Doppia deduzione logica”">​</a></h1><p>Anche qui non devi confondere la <strong>doppia deduzione logica</strong> con la coimplicazione:</p><p>La <strong>doppia deduzione logica</strong> (indicata col simbolo <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo>⇔</mo></mrow><annotation encoding="application/x-tex">\\Leftrightarrow</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.3669em;"></span><span class="mrel">⇔</span></span></span></span> che si legge <strong>se e solo se</strong>) è una procedura in base alla quale date due proposizioni <strong>Ipotesi</strong> e <strong>Tesi</strong> si può dimostrare</p><p><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mtext>da\xA0Ipotesi</mtext><mo>⇒</mo><mtext>Tesi</mtext></mrow><annotation encoding="application/x-tex">\\text{da Ipotesi} \\Rightarrow \\text{Tesi}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord text"><span class="mord">da\xA0Ipotesi</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">⇒</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord text"><span class="mord">Tesi</span></span></span></span></span></p><p>ed anche</p><p><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mtext>da\xA0Tesi</mtext><mo>⇒</mo><mtext>Ipotesi</mtext></mrow><annotation encoding="application/x-tex">\\text{da Tesi} \\Rightarrow \\text{Ipotesi}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.6944em;"></span><span class="mord text"><span class="mord">da\xA0Tesi</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">⇒</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.8778em;vertical-align:-0.1944em;"></span><span class="mord text"><span class="mord">Ipotesi</span></span></span></span></span></p><p>Il secondo è detto anche teorema inverso del primo.</p><p>Un teorema ed il suo inverso (se esiste) si possono unificare nel teorema:</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><mtext>Ipotesi</mtext><mo>⇔</mo><mtext>Tesi</mtext></mrow><annotation encoding="application/x-tex">\\text{Ipotesi} \\Leftrightarrow \\text{Tesi} </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.8778em;vertical-align:-0.1944em;"></span><span class="mord text"><span class="mord">Ipotesi</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">⇔</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="katex-base"><span class="katex-strut" style="height:0.6833em;"></span><span class="mord text"><span class="mord">Tesi</span></span></span></span></span></span></p><hr><h3 id="esempio" tabindex="-1">Esempio: <a class="header-anchor" href="#esempio" aria-label="Permalink to “Esempio:”">​</a></h3><p class="text-red">Teorema diretto: [<strong>se un triangolo ha due lati uguali allora ha due angoli uguali</strong>]</p><p class="text-red">Teorema inverso: [<strong>se un triangolo ha due angoli uguali allora ha due lati uguali</strong>]</p><p class="text-red">Unifichiamo nel teorema: [<strong>Un triangolo ha due lati uguali se e solo se ha due angoli uguali</strong>]</p><p>Quando abbiamo sia un teorema che il teorema inverso allora abbiamo una cosiddetta <strong>condizione necessaria e sufficiente</strong>.</p><p class="text-red">[<strong>Condizione necessaria e sufficiente perché un triangolo abbia due angoli uguali è che abbia due lati uguali</strong>]</p><p>Mentre, se esiste solamente il teorema diretto diremo che abbiamo solamente una <strong>condizione necessaria</strong>.</p><p class="text-red">[<strong>Se un quadrilatero è un rettangolo allora ha le due diagonali congruenti</strong>]</p><p>Essere un rettangolo è una condizione solamente necessaria perché non vale il teorema inverso:</p><hr><blockquote><p><strong>Il teorema inverso sarebbe:</strong> [<strong>Se un quadrilatero ha due diagonali congruenti allora è un rettangolo</strong>]{.text-red} ma non è vero: infatti per essere un rettangolo il quadrilatero deve anche essere un parallelogramma</p></blockquote><hr><p>In alcuni testi si usa il simbolo <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo>↔</mo></mrow><annotation encoding="application/x-tex">\\leftrightarrow</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.3669em;"></span><span class="mrel">↔</span></span></span></span> (una linea sola) per indicare la coimplicazione ed il simbolo <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo>⇔</mo></mrow><annotation encoding="application/x-tex">\\Leftrightarrow</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="katex-base"><span class="katex-strut" style="height:0.3669em;"></span><span class="mrel">⇔</span></span></span></span> (con doppia linea) per la doppia deduzione logica, ma in altri testi viene indicato diversamente.</p><p>Tu cerca di usare gli stessi simboli che usa il tuo Insegnante.</p>`,24)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};